-- Caring for Yourself (Krys and Taea, 2026-10-22): help for people gets its own page, apart from help for pets.
-- New help categories: crisis lines, abuse at home, mental health, and grieving a pet. Numbers checked 2026-10-22
-- on each organization's own site (988 and SAMHSA, Veterans Crisis Line, Crisis Text Line, The Trevor Project,
-- Trans Lifeline, the National DV Hotline, the Virginia Action Alliance, NAMI, the VACSB directory, Tufts, Lap of Love).
alter table public.help_resources drop constraint help_resources_category_check;
alter table public.help_resources add constraint help_resources_category_check
  check (category in ('food','vet','behavior','housing','rehoming','birds','financing','abuse','wildlife','wildgroups','crisis','dv','mental','grief'));

-- Safe Havens and RedRover's Safe Escape grants are for people leaving abuse with their pets: they move to the new page.
update public.help_resources set category = 'dv', sort = 30 where name = 'Safe Havens for Pets (Animal Welfare Institute)' and category = 'housing';
update public.help_resources set category = 'dv', sort = 40 where name = 'RedRover Relief Safe Escape Grants' and category = 'rehoming';

