insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'crisis', '988 Suicide & Crisis Lifeline', 'Call or text 988, or chat online, any time. Free and confidential, for anyone thinking about suicide or in emotional distress, or worried about someone who is. In English and Spanish.', null, 'https://988lifeline.org/', '988', 'Anywhere in the U.S.', date '2026-10-22', true, 10 where not exists (select 1 from public.help_resources where name = '988 Suicide & Crisis Lifeline');
insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'crisis', 'Veterans Crisis Line', 'For veterans, service members and the people who love them, even without VA benefits. Dial 988 then press 1, text 838255, or chat online.', null, 'https://www.veteranscrisisline.net/', '988, then press 1', 'Anywhere in the U.S.', date '2026-10-22', true, 20 where not exists (select 1 from public.help_resources where name = 'Veterans Crisis Line');
insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'crisis', 'Crisis Text Line', 'Text HOME to 741741 to reach a trained volunteer crisis counselor, any time.', null, 'https://www.crisistextline.org/', null, 'Anywhere in the U.S.', date '2026-10-22', true, 30 where not exists (select 1 from public.help_resources where name = 'Crisis Text Line');
insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'crisis', 'The Trevor Project', 'For LGBTQ+ young people: call, text START to 678-678, or chat online, any time.', null, 'https://www.thetrevorproject.org/get-help/', '1-866-488-7386', 'Anywhere in the U.S.', date '2026-10-22', true, 40 where not exists (select 1 from public.help_resources where name = 'The Trevor Project');
insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'crisis', 'Trans Lifeline', 'Peer support by and for trans people.', null, 'https://translifeline.org/hotline/', '(877) 565-8860', 'Anywhere in the U.S.', date '2026-10-22', true, 50 where not exists (select 1 from public.help_resources where name = 'Trans Lifeline');
insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'dv', 'National Domestic Violence Hotline', 'Call, text START to 88788, or chat online, any time. Advocates can help you make a safety plan, including for your pets.', null, 'https://www.thehotline.org/', '1-800-799-7233', 'Anywhere in the U.S.', date '2026-10-22', true, 60 where not exists (select 1 from public.help_resources where name = 'National Domestic Violence Hotline');
insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'dv', 'Virginia Statewide Hotline', 'Help with domestic and sexual violence anywhere in Virginia. Call any time, or text (804) 793-9999.', null, 'https://vsdvalliance.org/', '1-800-838-8238', 'All of Virginia', date '2026-10-22', true, 70 where not exists (select 1 from public.help_resources where name = 'Virginia Statewide Hotline');
insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'mental', 'NAMI HelpLine', 'Free information, support and referrals for anyone living with a mental health condition, and the people who love them. Call, or text NAMI to 62640.', 'Not a crisis line. In a crisis, call or text 988.', 'https://www.nami.org/support-education/nami-helpline/', '1-800-950-6264', 'Anywhere in the U.S.', date '2026-10-22', true, 80 where not exists (select 1 from public.help_resources where name = 'NAMI HelpLine');
insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'mental', 'SAMHSA National Helpline', 'Free, confidential help finding treatment for mental health and substance use, any time, in English and Spanish.', null, 'https://www.samhsa.gov/find-help/helplines/national-helpline', '1-800-662-4357', 'Anywhere in the U.S.', date '2026-10-22', true, 90 where not exists (select 1 from public.help_resources where name = 'SAMHSA National Helpline');
insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'mental', '211 Virginia', 'Dial 211 to find local help of all kinds, like counseling, support groups and help paying bills.', null, 'https://www.211virginia.org/', '211', 'All of Virginia', date '2026-10-22', true, 100 where not exists (select 1 from public.help_resources where name = '211 Virginia');
