insert into public.help_resources (category, name, description, caution, link_url, phone, area, checked_on, published, sort) select 'grief', 'Tufts Pet Loss Support Helpline', 'A free helpline run by Tufts veterinary students, for grieving a pet who died, or one you lost or had to give up. Answered 6 to 9 PM Eastern, Monday to Thursday, with voicemail any time.', null, 'https://vet.tufts.edu/pet-loss-support-helpline', '508-839-7966', 'Anywhere in the U.S.', date '2026-10-22', true, 170 where not exists (select 1 from public.help_resources where name = 'Tufts Pet Loss Support Helpline');
